23: public class JavaSerializationSessionValueSerializer implements SessionValueSerializer {
24: 
25:   @Override
26:   public <T> void serialize(Class<T> type, T value, OutputStream outputStream) throws IOException {
27:     ObjectOutputStream objectOutputStream = new ObjectOutputStream(outputStream);
28:     objectOutputStream.writeObject(value);
29:     objectOutputStream.flush();
30:   }
31: 
32:   @Override
33:   public <T> T deserialize(Class<T> type, InputStream inputStream) throws IOException {
34:     try {
35:       ObjectInputStream objectInputStream = new ObjectInputStream(inputStream);
36:       Object value = objectInputStream.readObject();
37:       if (type.isInstance(value)) {
38:         return type.cast(value);
39:       } else {
40:         throw new ClassCastException("Expected to read object of type " + type.getName() + " from string, but got: " + value.getClass().getName());
41:       }
42:     } catch (ClassNotFoundException e) {
43:       throw Exceptions.uncheck(e);
44:     }
45:   }
