39: public class DefaultSessionAdapter implements SessionAdapter {
40: 
41:   private final Map<String, String> strings = Maps.newHashMap();
42:   private final Map<Class<?>, byte[]> objects = Maps.newHashMap();
43: 
44:   private final SessionId sessionId;
45:   private final ByteBufAllocator bufferAllocator;
46:   private final SessionStoreAdapter storeAdapter;
47:   private final SessionStatus sessionStatus;
48:   private final SessionValueSerializer defaultSerializer;
49: 
50:   boolean needsLoad = true;
51:   private final SyncSession sync = new Sync();
52: 
53:   private static class Data implements Serializable {
54:     Map<String, String> strings;
55:     Map<Class<?>, byte[]> objects;
56: 
57:     public Data(Map<String, String> strings, Map<Class<?>, byte[]> objects) {
58:       this.strings = strings;
59:       this.objects = objects;
60:     }
61:   }
62: 
63:   public DefaultSessionAdapter(SessionId sessionId, ByteBufAllocator bufferAllocator, SessionStoreAdapter storeAdapter, SessionStatus sessionStatus, SessionValueSerializer defaultSerializer) {
64:     this.sessionId = sessionId;
65:     this.bufferAllocator = bufferAllocator;
66:     this.storeAdapter = storeAdapter;
67:     this.sessionStatus = sessionStatus;
68:     this.defaultSerializer = defaultSerializer;
69:   }
70: 
71:   @Override
72:   public Promise<SyncSession> getSync() {
73:     if (needsLoad) {
74:       return storeAdapter.load(sessionId, bufferAllocator).map(data -> {
75:         needsLoad = false;
76:         try {
77:           hydrate(data);
78:         } finally {
79:           data.release();
80:         }
81:         return sync;
82:       });
83:     } else {
84:       return execControl().promiseOf(sync);
85:     }
86:   }
87: 
88:   private void hydrate(ByteBuf data) {
89:     if (data.readableBytes() > 0) {
90:       try {
91:         Data deserializedData = defaultSerializer.deserialize(Data.class, new ByteBufInputStream(data));
92:         this.strings.clear();
93:         this.strings.putAll(deserializedData.strings);
94:         this.objects.clear();
95:         this.objects.putAll(deserializedData.objects);
96:         sessionStatus.setDirty(false);
97:       } catch (Exception e) {
98:         throw Exceptions.uncheck(e);
99:       }
100:     }
101:   }
102: 
103: 
104:   @Override
105:   public boolean isDirty() {
106:     return sessionStatus.isDirty();
107:   }
108: 
109:   private ByteBuf serialize() {
110:     Data data = new Data(ImmutableMap.copyOf(strings), ImmutableMap.copyOf(objects));
111:     ByteBuf buffer = bufferAllocator.buffer();
112:     OutputStream outputStream = new ByteBufOutputStream(buffer);
113:     try {
114:       defaultSerializer.serialize(Data.class, data, outputStream);
115:       outputStream.close();
116:       return buffer;
117:     } catch (Throwable e) {
118:       buffer.release();
119:       throw Exceptions.uncheck(e);
120:     }
121:   }
122: 
123:   @Override
124:   public Operation save() {
125:     return storeAdapter.store(sessionId, bufferAllocator, serialize())
126:       .next(() -> {
127:         sessionStatus.setDirty(false);
128:       });
