74:   public static class ApplicationConstants {
75:     private final RenderController renderController;
76:     private final ExecController execController;
77:     private final ServerConfig serverConfig;
78:     private final Handler end;
79: 
80:     public ApplicationConstants(Registry registry, RenderController renderController, ExecController execController, Handler end) {
81:       this.renderController = renderController;
82:       this.execController = execController;
83:       this.serverConfig = registry.get(ServerConfig.class);
