89:     private final ApplicationConstants applicationConstants;
90: 
91:     private final DefaultRequest request;
92: 
93:     private final DirectChannelAccess directChannelAccess;
94:     private final EventRegistry<RequestOutcome> responseTransmitter;
95:     private Execution execution;
96: 
97:     private final Deque<ChainIndex> indexes = new ArrayDeque<>();
98: 
99:     public Response response;
100:     public Context context;
101:     public Handler handler;
102: 
103:     public RequestConstants(
104:       ApplicationConstants applicationConstants, DefaultRequest request,
105:       DirectChannelAccess directChannelAccess, EventRegistry<RequestOutcome> responseTransmitter
106:     ) {
107:       this.applicationConstants = applicationConstants;
108:       this.request = request;
109:       this.directChannelAccess = directChannelAccess;
110:       this.responseTransmitter = responseTransmitter;
