166:   private static class ContextRegistry implements DelegatingRegistry {
167:     private final DefaultContext context;
168: 
169:     public ContextRegistry(DefaultContext context) {
170:       this.context = context;
171:     }
172: 
173:     @Override
174:     public Registry getDelegate() {
175:       return context.getCurrentRegistry();
176:     }
177:   }
