210:   public void next() {
211:     Handler handler = null;
212: 
213:     ChainIndex index = requestConstants.indexes.peek();
214:     while (handler == null) {
215:       if (index.hasNext()) {
216:         handler = index.next();
217:         if (handler.getClass().equals(ChainHandler.class)) {
218:           requestConstants.indexes.push(new ChainIndex(((ChainHandler) handler).getHandlers(), getCurrentRegistry(), false));
219:           index = requestConstants.indexes.peek();
220:           handler = null;
221:         }
222:       } else if (index.first) {
223:         handler = requestConstants.applicationConstants.end;
224:       } else {
225:         requestConstants.indexes.pop();
226:         index = requestConstants.indexes.peek();
227:       }
228:     }
229: 
230:     try {
231:       requestConstants.handler = handler;
232:       handler.handle(this);
233:     } catch (Throwable e) {
234:       if (e instanceof HandlerException) {
235:         throw (HandlerException) e;
236:       } else {
237:         throw new HandlerException(e);
238:       }
239:     }
240:   }
