17: package ratpack.server.internal;
18: 
19: import com.google.common.base.Splitter;
20: import com.google.common.base.Strings;
21: import com.google.common.collect.Iterables;
22: import com.google.common.net.HostAndPort;
23: import ratpack.handling.Context;
24: import ratpack.http.Headers;
25: import ratpack.server.PublicAddress;
26: import ratpack.util.Exceptions;
27: import ratpack.util.internal.ProtocolUtil;
28: 
29: import java.net.URI;
30: import java.net.URISyntaxException;
31: 
32: import static ratpack.http.internal.HttpHeaderConstants.*;
33: import static ratpack.util.internal.ProtocolUtil.HTTPS_SCHEME;
34: 
35: public class InferringPublicAddress implements PublicAddress {
36: 
37:   private static final Splitter FORWARDED_HOST_SPLITTER = Splitter.on(',').trimResults().omitEmptyStrings();
38: 
39:   private final String scheme;
40: 
41:   public InferringPublicAddress(String scheme) {
42:     this.scheme = scheme;
43:   }
44: 
45:   public URI get(Context ctx) {
46:     String scheme;
47:     String host;
48:     int port;
49:     HostAndPort forwardedHostData = getForwardedHostData(ctx);
50:     if (forwardedHostData != null) {
51:       scheme = determineScheme(ctx, this.scheme);
52:       host = forwardedHostData.getHostText();
53:       port = forwardedHostData.getPortOrDefault(-1);
54:     } else {
55:       URI absoluteRequestURI = getAbsoluteRequestUri(ctx);
56:       if (absoluteRequestURI != null) {
57:         scheme = determineScheme(ctx, absoluteRequestURI.getScheme());
58:         host = absoluteRequestURI.getHost();
59:         port = absoluteRequestURI.getPort();
60:       } else {
61:         scheme = determineScheme(ctx, this.scheme);
62:         HostAndPort hostData = getHostData(ctx);
63:         if (hostData != null) {
64:           host = hostData.getHostText();
65:           port = hostData.getPortOrDefault(-1);
66:         } else {
67:           HostAndPort localAddress = ctx.getRequest().getLocalAddress();
68:           host = localAddress.getHostText();
69:           port = ProtocolUtil.isDefaultPortForScheme(localAddress.getPort(), this.scheme) ? -1 : localAddress.getPort();
70:         }
71:       }
72:     }
73:     try {
74:       return new URI(scheme, null, host, port, null, null, null);
75:     } catch (URISyntaxException ex) {
76:       throw Exceptions.uncheck(ex);
77:     }
78:   }
79: 
80:   private URI getAbsoluteRequestUri(Context context) {
81:     String rawUri = Strings.nullToEmpty(context.getRequest().getRawUri());
82:     if (rawUri.isEmpty() || rawUri.startsWith("/")) {
83:       return null;
84:     }
85:     return URI.create(rawUri);
86:   }
87: 
88:   private HostAndPort getForwardedHostData(Context context) {
89:     Headers headers = context.getRequest().getHeaders();
90:     String forwardedHostHeader = Strings.emptyToNull(headers.get(X_FORWARDED_HOST.toString()));
91:     String hostPortString = forwardedHostHeader != null ? Iterables.getFirst(FORWARDED_HOST_SPLITTER.split(forwardedHostHeader), null) : null;
92:     return hostPortString != null ? HostAndPort.fromString(hostPortString) : null;
93:   }
94: 
95:   private HostAndPort getHostData(Context context) {
96:     Headers headers = context.getRequest().getHeaders();
97:     String hostPortString = Strings.emptyToNull(headers.get(HOST.toString()));
98:     return hostPortString != null ? HostAndPort.fromString(hostPortString) : null;
99:   }
100: 
101:   private String determineScheme(Context context, String defaultScheme) {
102:     Headers headers = context.getRequest().getHeaders();
103:     String forwardedSsl = headers.get(X_FORWARDED_SSL.toString());
104:     String forwardedProto = headers.get(X_FORWARDED_PROTO.toString());
105:     if (ON.toString().equalsIgnoreCase(forwardedSsl)) {
106:       return HTTPS_SCHEME;
107:     }
108:     return forwardedProto != null ? forwardedProto : defaultScheme;
109:   }
110: }
