28: public class DefaultPromise<T> implements Promise<T> {
29: 
30:   private final Upstream<T> upstream;
31: 
32:   public DefaultPromise(Upstream<T> upstream) {
33:     this.upstream = upstream;
34:   }
35: 
36:   @Override
37:   public void then(final Action<? super T> then) {
38:     try {
39:       upstream.connect(new Downstream<T>() {
40:         @Override
41:         public void success(T value) {
42:           try {
43:             then.execute(value);
44:           } catch (Throwable e) {
45:             throwError(e);
46:           }
47:         }
48: 
49:         @Override
50:         public void error(Throwable throwable) {
51:           throwError(throwable);
52:         }
53: 
54:         @Override
55:         public void complete() {}
56:       });
57:     } catch (ExecutionException e) {
58:       throw e;
59:     } catch (Exception e) {
60:       throw new InternalRatpackError("failed to add promise resume action", e);
61:     }
62:   }
63: 
64:   private void throwError(Throwable throwable) {
65:     ExecutionBacking.require().streamSubscribe(h ->
66:         h.complete(() -> {
67:           throw Exceptions.toException(throwable);
68:         })
69:     );
70:   }
71: 
72:   @Override
73:   public <O> Promise<O> transform(Function<? super Upstream<? extends T>, ? extends Upstream<O>> upstreamTransformer) {
74:     try {
75:       return new DefaultPromise<>(upstreamTransformer.apply(upstream));
76:     } catch (Exception e) {
77:       throw Exceptions.uncheck(e);
78:     }
79:   }
80: 
81:   @Override
82:   public T await() throws Exception {
83:     ExecutionBacking backing = ExecutionBacking.require();
84:     CountDownLatch latch = new CountDownLatch(1);
85:     AtomicReference<Result<T>> result = new AtomicReference<>();
86:     backing.streamSubscribe(handle ->
87:         upstream.connect(
88:           new Downstream<T>() {
89:             @Override
90:             public void success(T value) {
91:               unlatch(Result.success(value));
92:             }
93: 
94:             @Override
95:             public void error(Throwable throwable) {
96:               unlatch(Result.error(throwable));
97:             }
98: 
99:             @Override
100:             public void complete() {
101:               unlatch(Result.success(null));
102:             }
103: 
104:             private void unlatch(Result<T> success) {
105:               result.set(success);
106:               latch.countDown();
107:               handle.complete();
108:             }
109:           }
110:         )
111:     );
112:     backing.eventLoopDrain();
113:     latch.await();
