56:   private final static Logger LOGGER = LoggerFactory.getLogger(DefaultResponseTransmitter.class);
57:   private static final Runnable NOOP_RUNNABLE = () -> {
58:   };
59:   private static final ChannelFutureListener CHANNEL_READ = f -> f.channel().read();
60: 
61:   private final AtomicBoolean transmitted;
62:   private final Channel channel;
63:   private final Request ratpackRequest;
64:   private final HttpHeaders responseHeaders;
65:   private final RequestBodyAccumulator requestBodyAccumulator;
66:   private final boolean isSsl;
67: 
68:   private List<Action<? super RequestOutcome>> outcomeListeners;
