75:   public DefaultResponseTransmitter(AtomicBoolean transmitted, Channel channel, HttpRequest nettyRequest, Request ratpackRequest, HttpHeaders responseHeaders, @Nullable RequestBodyAccumulator requestBodyAccumulator) {
76:     this.transmitted = transmitted;
77:     this.channel = channel;
78:     this.ratpackRequest = ratpackRequest;
79:     this.responseHeaders = responseHeaders;
80:     this.requestBodyAccumulator = requestBodyAccumulator;
81:     this.isKeepAlive = HttpUtil.isKeepAlive(nettyRequest);
82:     this.isSsl = channel.pipeline().get(SslHandler.class) != null;
83:   }
