121:   private void transmit(final HttpResponseStatus responseStatus, Object body, boolean sendLastHttpContent) {
122:     ChannelFuture channelFuture = pre(responseStatus);
123:     if (channelFuture == null) {
124:       ReferenceCountUtil.release(body);
125:       return;
126:     }
127: 
128:     channelFuture.addListener(future -> {
129:       if (channel.isOpen()) {
130:         if (sendLastHttpContent) {
131:           channel.write(body);
132:           post(responseStatus);
133:         } else {
134:           post(responseStatus, channel.writeAndFlush(body));
135:         }
136:       } else {
137:         ReferenceCountUtil.release(body);
138:       }
139:     });
140:   }
