146:     boolean compress = !responseHeaders.contains(HttpHeaderConstants.CONTENT_ENCODING, HttpHeaderConstants.IDENTITY, true);
147: 
148:     if (!isSsl && !compress && file.getFileSystem().equals(FileSystems.getDefault())) {
149:       Blocking.get(() -> new FileInputStream(file.toFile()).getChannel()).then(fileChannel -> {
150:         FileRegion defaultFileRegion = new DefaultFileRegion(fileChannel, 0, size);
151:         transmit(status, defaultFileRegion, true);
152:       });
153:     } else {
154:       Blocking.get(() ->
155:         Files.newByteChannel(file)
156:       ).then(fileChannel ->
