165:       private Subscription subscription;
166: 
167:       private final AtomicBoolean done = new AtomicBoolean();
168: 
169:       private final ChannelFutureListener cancelOnFailure = future -> {
170:         if (!future.isSuccess()) {
171:           cancel();
172:         }
173:       };
174: 
175:       private final GenericFutureListener<Future<? super Void>> cancelOnCloseListener =
176:         c -> cancel();
177: 
178:       private void cancel() {
179:         channel.closeFuture().removeListener(cancelOnCloseListener);
180:         if (done.compareAndSet(false, true)) {
181:           subscription.cancel();
182:           post(responseStatus);
183:         }
184:       }
185: 
186:       @Override
187:       public void onSubscribe(Subscription subscription) {
188:         if (subscription == null) {
189:           throw new NullPointerException("'subscription' is null");
190:         }
191:         if (this.subscription != null) {
192:           subscription.cancel();
193:           return;
194:         }
195: 
196:         this.subscription = subscription;
197: 
198:         onWritabilityChanged = () -> {
199:           if (channel.isWritable() && !done.get()) {
200:             this.subscription.request(1);
201:           }
202:         };
203: 
204:         channel.closeFuture().addListener(cancelOnCloseListener);
205: 
206:         ChannelFuture channelFuture = pre(responseStatus);
207:         if (channelFuture == null) {
208:           subscription.cancel();
209:           notifyListeners(responseStatus, channel.close());
210:         } else {
211:           channelFuture.addListener(cancelOnFailure);
212:           if (channel.isWritable()) {
213:             this.subscription.request(1);
214:           }
215:         }
216:       }
217: 
218:       @Override
219:       public void onNext(ByteBuf o) {
220:         o.touch();
221:         if (channel.isOpen()) {
222:           channel.writeAndFlush(new DefaultHttpContent(o)).addListener(cancelOnFailure);
223:           if (channel.isWritable()) {
224:             subscription.request(1);
225:           }
226:         } else {
227:           o.release();
228:           cancel();
229:         }
230:       }
231: 
232:       @Override
233:       public void onError(Throwable t) {
234:         if (t == null) {
235:           throw new NullPointerException("error is null");
236:         }
237:         LOGGER.warn("Exception thrown transmitting stream", t);
238:         if (done.compareAndSet(false, true)) {
239:           channel.closeFuture().removeListener(cancelOnCloseListener);
240:           post(responseStatus);
241:         }
242:       }
243: 
244:       @Override
245:       public void onComplete() {
246:         if (done.compareAndSet(false, true)) {
247:           channel.closeFuture().removeListener(cancelOnCloseListener);
248:           post(responseStatus);
249:         }
250:       }
251:     };
252:   }
