258:   private void post(HttpResponseStatus responseStatus, ChannelFuture lastContentFuture) {
259:     if (channel.isOpen()) {
260:       if (isKeepAlive) {
261:         lastContentFuture.addListener(CHANNEL_READ);
262:       } else {
263:         lastContentFuture.addListener(ChannelFutureListener.CLOSE);
264:       }
265:       notifyListeners(responseStatus, lastContentFuture);
266:     } else {
267:       notifyListeners(responseStatus, channel.newSucceededFuture());
268:     }
269:   }
270: 
271:   private void notifyListeners(final HttpResponseStatus responseStatus, ChannelFuture future) {
272:     if (outcomeListeners != null) {
273:       future.addListener(ignore -> {
274:         channel.attr(ATTRIBUTE_KEY).set(null);
275:         SentResponse sentResponse = new DefaultSentResponse(new NettyHeadersBackedHeaders(responseHeaders), new DefaultStatus(responseStatus));
276:         RequestOutcome requestOutcome = new DefaultRequestOutcome(ratpackRequest, sentResponse, stopTime);
277:         for (Action<? super RequestOutcome> outcomeListener : outcomeListeners) {
278:           try {
279:             outcomeListener.execute(requestOutcome);
280:           } catch (Exception e) {
281:             LOGGER.warn("request outcome listener " + outcomeListener + " threw exception", e);
282:           }
283:         }
284:       });
285:     }
286:   }
287: 
288:   public void writabilityChanged() {
289:     onWritabilityChanged.run();
290:   }
291: 
292:   @Override
293:   public void addOutcomeListener(Action<? super RequestOutcome> action) {
294:     if (outcomeListeners == null) {
295:       outcomeListeners = new ArrayList<>(1);
296:     }
297:     outcomeListeners.add(action);
298:   }
299: 
300:   @Override
301:   public void forceCloseConnection() {
302:     responseHeaders.set(HttpHeaderNames.CONNECTION, HttpHeaderValues.CLOSE);
303:   }
304: }
