41: public class CookieBasedSessionStorageBindingHandler implements Handler {
42: 
43:   private final String session_separator = ":";
44:   private final String sessionName;
45:   private final Handler handler;
46: 
47:   public CookieBasedSessionStorageBindingHandler(String sessionName, Handler handler) {
48:     this.sessionName = sessionName;
49:     this.handler = handler;
50:   }
51: 
52:   public void handle(final Context context) {
53:     context.getRequest().addLazy(SessionStorage.class, createSessionStorage(context));
54:     context.getResponse().beforeSend(serializeSession(context));
55:     context.insert(handler);
56:   }
