58:   private Supplier<SessionStorage> createSessionStorage(Context context) {
59:     return () -> {
60:       Cookie cookieSession = context.getRequest()
61:         .getCookies()
62:         .stream()
63:         .filter(cookie -> sessionName.equals(cookie.getName()))
64:         .findFirst().orElse(null);
65:       DefaultSessionStorage storage = new DefaultSessionStorage(deserializeSession(context, cookieSession));
66:       context.getRequest().add(StorageHashContainer.class, new StorageHashContainer(storage.hashCode()));
