71:   private String getEncodedPair(Map.Entry<String, Object> pairs) {
72:     String encoded = null;
73:     try {
74:       encoded = URLEncoder.encode(pairs.getKey(), "utf-8") + "=" + URLEncoder.encode(pairs.getValue().toString(), "utf-8");
75:     } catch (UnsupportedEncodingException e) {
76:       throw new RuntimeException(e);
77:     }
