81:   private Action<ResponseMetaData> serializeSession(Context context) {
82:     SessionStorage storage = context.getRequest()
83:       .maybeGet(SessionStorage.class)
84:       .orElse(null);
85:     return responseMetaData -> {
86:       if (storage != null) {
87:         boolean hasChanged = context.getRequest().get(StorageHashContainer.class).getHashCode() != storage.hashCode();
88:         if (hasChanged) {
89:           String encodedPairs = storage
90:             .entrySet()
91:             .stream()
92:             .map(this::getEncodedPair)
93:             .collect(Collectors.joining("&"));
94: 
95:           if (encodedPairs == null || encodedPairs.isEmpty()) {
96:             invalidateSession(responseMetaData);
97:           } else {
98:             String s = Base64.getUrlEncoder().encodeToString(encodedPairs.getBytes("utf-8"));
99:             String digest = context.get(Crypto.class).sign(encodedPairs);
100: 
101:             responseMetaData.cookie(sessionName, s + session_separator + digest);
102:           }
103:         }
104:       }
105:     };
106:   }
