112:   private ConcurrentMap<String, Object> deserializeSession(Context context, Cookie cookieSession) {
113:     ConcurrentMap<String, Object> sessionStorage = new ConcurrentHashMap<>();
114: 
115:     String encodedPairs = cookieSession == null ? null : cookieSession.getValue();
116:     if (encodedPairs != null) {
117:       String[] parts = encodedPairs.split(session_separator);
118:       if (parts.length == 2) {
119:         String encoded = parts[0];
120:         String digest = parts[1];
121: 
122:         Crypto crypto = context.get(Crypto.class);
123:         try {
124:           byte[] pairs = Base64.getUrlDecoder().decode(encoded.getBytes("utf-8"));
125:           String unpacked = new String(pairs);
126: 
127:           if (crypto.sign(unpacked).equals(digest)) {
128: 
129:             Arrays.stream(unpacked.split("&")).map(s -> {
130:               String[] pair = s.split("=");
131:               return Pair.of(pair[0], pair[1]);
132:             }).forEach(getDecodedPairs(sessionStorage));
133: 
134:           }
135:         } catch (Exception e) {
136:           throw new RuntimeException(e);
137:         }
138:       }
139: 
140:     }
141: 
142:     return sessionStorage;
143:   }
