145:   private Consumer<Pair<String, String>> getDecodedPairs(ConcurrentMap<String, Object> sessionStorage) throws UnsupportedEncodingException {
146:     return p -> {
147:       try {
148:         String key = URLDecoder.decode(p.getLeft(), "utf-8");
149:         String value = URLDecoder.decode(p.getRight(), "utf-8");
150:         sessionStorage.put(key, value);
151:       } catch (UnsupportedEncodingException e) {
152:         throw new RuntimeException(e);
153:       }
154:     };
155:   }
