30: public class DefaultRxBackground implements RxBackground {
31: 
32:   private final Background background;
33: 
34:   @Inject
35:   public DefaultRxBackground(Background background) {
36:     this.background = background;
37:   }
38: 
39:   @Override
40:   public <T> Observable<T> observe(final Callable<T> promise) {
41:     return Observable.create(new OnSubscribe<>(promise, new Action2<T, Subscriber<? super T>>() {
42:       @Override
43:       public void call(T thing, Subscriber<? super T> subscriber) {
44:         subscriber.onNext(thing);
45:       }
46:     }));
47:   }
48: 
49:   @Override
50:   public <I extends Iterable<T>, T> Observable<T> observeEach(final Callable<I> promise) {
51:     return Observable.create(new OnSubscribe<>(promise, new Action2<I, Subscriber<? super T>>() {
52:       @Override
53:       public void call(I things, Subscriber<? super T> subscriber) {
54:         for (T thing : things) {
55:           subscriber.onNext(thing);
56:         }
57:       }
58:     }));
59:   }
60: 
61:   private class OnSubscribe<T, S> implements Observable.OnSubscribe<S> {
62:     private final Callable<T> promise;
63:     private final Action2<T, Subscriber<? super S>> emitter;
64: 
65:     public OnSubscribe(Callable<T> callable, Action2<T, Subscriber<? super S>> emitter) {
66:       this.promise = callable;
67:       this.emitter = emitter;
68:     }
69: 
