34: public class ReloadableFileBackedFactory<T> implements Factory<T> {
35: 
36:   // Note: we are blocking for IO on the main thread here, but it only really impacts
37:   // reloadable mode so it's not worth the complication of jumping off the main thread
38: 
39:   private final Path file;
40:   private final boolean reloadable;
41:   private final Producer<T> producer;
42:   private final Releaser<T> releaser;
43: 
44:   private final AtomicReference<FileTime> lastModifiedHolder = new AtomicReference<>(null);
45:   private final AtomicReference<ByteBuf> contentHolder = new AtomicReference<>();
46:   private final AtomicReference<T> delegateHolder = new AtomicReference<>(null);
47:   private final Lock lock = new ReentrantLock();
48: 
49:   public interface Producer<T> {
50:     T produce(Path file, ByteBuf content) throws Exception;
51:   }
52: 
53:   public interface Releaser<T> {
54:     void release(T thing);
55:   }
56: 
57:   private static class NullReleaser<T> implements Releaser<T> {
58:     @Override
59:     public void release(T thing) {
60: 
61:     }
62:   }
63: 
64:   public ReloadableFileBackedFactory(Path file, boolean reloadable, Producer<T> producer) {
65:     this(file, reloadable, producer, new NullReleaser<>());
66:   }
67: 
68:   public ReloadableFileBackedFactory(Path file, boolean reloadable, Producer<T> producer, Releaser<T> releaser) {
69:     this.file = file;
70:     this.reloadable = reloadable;
71:     this.producer = producer;
72:     this.releaser = releaser;
73: 
74:     if (!reloadable) {
75:       try {
76:         refresh();
77:       } catch (Exception e) {
78:         throw uncheck(e);
79:       }
80:     }
81:   }
82: 
83:   public T create() {
84:     if (!reloadable) {
85:       return delegateHolder.get();
86:     }
87: 
88:     // If the file disappeared, wait a little for it to appear
89:     int i = 10;
90:     while (!Files.exists(file) && --i > 0) {
91:       try {
92:         Thread.sleep(100);
93:       } catch (InterruptedException e) {
94:         throw uncheck(e);
95:       }
96:     }
97: 
98:     if (!Files.exists(file)) {
99:       return null;
100:     }
101: 
102:     try {
103:       if (refreshNeeded()) {
104:         refresh();
105:       }
106:     } catch (Exception e) {
107:       throw uncheck(e);
108:     }
109: 
110:     return delegateHolder.get();
111:   }
112: 
113:   private boolean isContentSame() throws IOException {
114:     lock.lock();
115:     try {
116:       ByteBuf existing = contentHolder.get();
117:       //noinspection SimplifiableIfStatement
118:       if (existing == null) {
119:         return false;
120:       }
121: 
122:       return IoUtils.read(UnpooledByteBufAllocator.DEFAULT, file).equals(existing);
123:     } finally {
124:       lock.unlock();
125:     }
126:   }
127: 
128:   private boolean refreshNeeded() throws IOException {
129:     return !Files.getLastModifiedTime(file).equals(lastModifiedHolder.get()) || !isContentSame();
130:   }
131: 
132:   private void refresh() throws Exception {
133:     lock.lock();
134:     try {
135:       FileTime lastModifiedTime = Files.getLastModifiedTime(file);
136:       ByteBuf bytes = IoUtils.read(UnpooledByteBufAllocator.DEFAULT, file);
137: 
138:       if (lastModifiedTime.equals(lastModifiedHolder.get()) && bytes.equals(contentHolder.get())) {
139:         return;
140:       }
141: 
142:       T previous = delegateHolder.getAndSet(null);
143:       if (previous != null) {
144:         releaser.release(previous);
145:       }
146:       delegateHolder.set(producer.produce(file, bytes));
147: 
148:       this.lastModifiedHolder.set(lastModifiedTime);
149:       this.contentHolder.set(bytes);
150:     } finally {
151:       lock.unlock();
152:     }
153:   }
154: 
155: 
