41:   private final ConcurrentLinkedQueue<Fulfiller<T>> waiting = new ConcurrentLinkedQueue<>();
42:   private final AtomicBoolean draining = new AtomicBoolean();
43:   private final AtomicReference<Result<T>> result = new AtomicReference<>();
