165:         List<Throwable> seen = Lists.newArrayListWithCapacity(0);
166:         this.onError = t -> {
167:           if (seen.size() < MAX_ERRORS_THRESHOLD) {
168:             seen.add(t);
169:             onError.execute(t);
170:           } else {
171:             seen.forEach(t::addSuppressed);
172:             ExecutionBacking.LOGGER.error("Error handler " + onError + "reached maximum error threshold (might be caught in an error loop)", t);
173:           }
