195:       Iterator<Map.Entry<String, Object>> parts = params.entries().iterator();
196:       if (parts.hasNext()) {
197:         Map.Entry<String, Object> entry = parts.next();
198:         stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(entry.getKey()));
199:         String value = entry.getValue().toString();
200:         if (value != null && value.length() > 0) {
201:           stringBuilder.append("=");
202:           stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(value));
203:         }
204:         while (parts.hasNext()) {
205:           stringBuilder.append("&");
206:           Map.Entry<String, Object> e = parts.next();
207:           stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(e.getKey()));
208:           String v = e.getValue().toString();
209:           if (v != null && v.length() > 0) {
210:             stringBuilder.append("=");
211:             stringBuilder.append(UrlEscapers.urlFormParameterEscaper().escape(v));
212:           }
213:         }
214:       }
215:     }
216:   }
217: 
218: 
219:   @Override
220:   public String toString() {
221:     StringBuilder uri = new StringBuilder(protocol).append("://").append(host);
222:     if (port > -1) {
223:       uri.append(":").append(port);
224:     }
225:     appendPathString(uri);
226:     if (hasTrailingSlash) {
227:       uri.append("/");
228:     }
229:     appendQueryString(uri);
230: 
231:     return uri.toString();
232:   }
