235:     String requestContentType = request.getContentType().getType();
236:     if (requestContentType == null) {
237:       requestContentType = "text/plain";
238:     }
239:     T parsed;
240:     for (Parser<?, ?> parser : all) {
241:       parsed = maybeParse(requestContentType, parse, parser);
242:       if (parsed != null) {
243:         return parsed;
244:       }
245:     }
246: 
247:     throw new RuntimeException("No parser for " + parse + " and content type " + requestContentType);
