261:     if (requestContentType.equalsIgnoreCase(parser.getContentType()) && parser.getParseType().isInstance(parseSpec)) {
262:       @SuppressWarnings("unchecked") Parser<P, S> castParser = (Parser<P, S>) parser;
263:       RequestBody requestBody = new ByteBufBackedRequestBody(getRequest(), getRequest().getBuffer());
264:       return castParser.parse(this, requestBody, parseSpec);
265:     } else {
