296:     Date ifModifiedSinceHeader = request.getHeaders().getDate(IF_MODIFIED_SINCE);
297:     long lastModifiedSecs = date.getTime() / 1000;
298: 
299:     if (ifModifiedSinceHeader != null) {
300:       long time = ifModifiedSinceHeader.getTime();
301:       long ifModifiedSinceSecs = time / 1000;
302: 
303:       if (lastModifiedSecs == ifModifiedSinceSecs) {
304:         response.status(NOT_MODIFIED.code(), NOT_MODIFIED.reasonPhrase()).send();
305:         return;
306:       }
307:     }
308: 
309:     response.getHeaders().setDate(HttpHeaders.Names.LAST_MODIFIED, date);
310:     runnable.run();
311:   }
