318:   public void error(Exception exception) {
319:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
320: 
321:     Exception unpacked = unpackException(exception);
322: 
323:     try {
324:       serverErrorHandler.error(this, unpacked);
325:     } catch (Exception errorHandlerException) {
326:       StringWriter stringWriter = new StringWriter();
327:       PrintWriter printWriter = new PrintWriter(stringWriter);
328:       stringWriter.
329:         append("Exception thrown by error handler ").
330:         append(serverErrorHandler.toString()).
331:         append(" while handling exception\nOriginal exception: ");
332:       unpacked.printStackTrace(printWriter);
333:       stringWriter.
334:         append("Error handler exception: ");
335:       errorHandlerException.printStackTrace(printWriter);
336:       LOGGER.warning(stringWriter.toString());
337:       response.status(500).send();
338:     }
339:   }
