378:         if (result.isFailure()) {
379:           dispatchException(result.getFailure());
380:         } else {
381:           try {
382:             action.execute(result.getValue());
383:           } catch (Exception e) {
384:             dispatchException(e);
385:           }
386:         }
387:       }
388:     };
