158: 
159:   /**
160:    * Returns all of the objects whose declared type is assignment compatible with the given type.
161:    *
162:    * @param type the type of objects to search for
163:    * @param <O> the type of objects to search for
164:    * @return All objects of the given type
165:    */
166:   default <O> Iterable<? extends O> getAll(Class<O> type) {
167:     return getAll(TypeToken.of(type));
168:   }
169: 
170:   /**
171:    * Returns all of the objects whose declared type is assignment compatible with the given type.
172:    *
173:    * @param type the type of objects to search for
174:    * @param <O> the type of objects to search for
175:    * @return All objects of the given type
176:    */
177:   <O> Iterable<? extends O> getAll(TypeToken<O> type);
178: 
179:   /**
180:    * Find and transform an item.
181:    * <p>
182:    * This method will apply the given function to items in the order returned by {@link #getAll(TypeToken)} until the function returns a non null value.
183:    * The first non null value will be returned by this method immediately (as an optional).
184:    * If the function returns a null value for every item, an empty optional is returned.
