255:    *     Registry parent = registry().add(Thing.class, new ThingImpl("parent-1")).add(Thing.class, new ThingImpl("parent-2")).build();
256:    *     Registry joined = parent.join(child);
257:    *
258:    *     assertEquals("child-2", joined.get(Thing.class).getName());
259:    *     List<Thing> all = Lists.newArrayList(joined.getAll(Thing.class));
