331:    * @see RegistryBuilder#addLazy(Class, Supplier)
332:    */
333:   static <T> Registry single(Class<T> publicType, Supplier<? extends T> supplier) {
334:     return registry().addLazy(publicType, supplier).build();
335:   }
336: 
337:   /**
338:    * Creates a single entry registry, using {@link RegistryBuilder#add(Object)}.
339:    *
340:    * @param object the entry object
341:    * @return a new single entry registry
342:    * @see RegistryBuilder#add(java.lang.Object)
343:    */
344:   static Registry single(Object object) {
