350:    *
351:    * @param publicType the public type of the entry
352:    * @param implementation the entry object
353:    * @param <T> the public type of the entry
354:    * @return a new single entry registry
355:    * @see RegistryBuilder#add(Class, Object)
356:    */
357:   static <T> Registry single(Class<? super T> publicType, T implementation) {
358:     return registry().add(publicType, implementation).build();
359:   }
