50: public class CachingSupplierRegistry implements Registry {
51:   private final Function<TypeToken<?>, List<? extends Supplier<?>>> suppliersForTypeFunction;
52: 
53:   public CachingSupplierRegistry(Function<TypeToken<?>, List<? extends Supplier<?>>> suppliersForTypeFunction) {
54:     this.suppliersForTypeFunction = suppliersForTypeFunction;
55:   }
