64:   private final LoadingCache<PredicateCacheability.CacheKey<?>, List<? extends Supplier<?>>> predicateCache = CacheBuilder.newBuilder().build(new CacheLoader<PredicateCacheability.CacheKey<?>, List<? extends Supplier<?>>>() {
65:     @Override
66:     public List<? extends Supplier<?>> load(@SuppressWarnings("NullableProblems") PredicateCacheability.CacheKey<?> key) throws Exception {
67:       return get(key);
68:     }
