376:     throwable = unpackThrowable(throwable);
377: 
378:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.class).orElse(null);
379:     if (throwableHolder == null) {
380:       getRequest().add(ThrowableHolder.class, new ThrowableHolder(throwable));
381: 
382:       try {
383:         serverErrorHandler.error(this, throwable);
384:       } catch (Throwable errorHandlerThrowable) {
385:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
386:       }
387:     } else {
388:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
389:     }
390:   }
