115:   private static class ChainIndex implements Iterator<Handler> {
116:     final Handler[] handlers;
117:     Registry registry;
118:     final boolean first;
119:     int i;
120: 
121:     private ChainIndex(Handler[] handlers, Registry registry, boolean first) {
122:       this.handlers = handlers;
123:       this.registry = registry;
124:       this.first = first;
125:     }
126: 
127:     public Handler next() {
128:       return handlers[i++];
129:     }
