139:   public static void start(EventLoop eventLoop, ExecControl execControl, final RequestConstants requestConstants, Registry registry, Handler[] handlers, Action<? super Execution> onComplete) {
140:     ChainIndex index = new ChainIndex(handlers, registry, true);
141:     requestConstants.indexes.push(index);
142: 
143:     DefaultContext context = new DefaultContext(requestConstants);
144:     requestConstants.context = context;
145: 
146:     execControl.exec()
147:       .onError(throwable -> requestConstants.context.error(throwable instanceof HandlerException ? throwable.getCause() : throwable))
148:       .onComplete(onComplete)
149:       .eventLoop(eventLoop)
