17: package org.ratpackframework.path.internal;
18: 
19: import org.ratpackframework.path.PathBinding;
20: import org.ratpackframework.util.internal.CollectionUtils;
21: 
22: import java.util.LinkedHashMap;
23: import java.util.Map;
24: 
25: public class DefaultPathBinding implements PathBinding {
26: 
27:   private final String binding;
28:   private final String bindingTerminated;
29:   private final String pastBinding;
30: 
31:   private final Map<String, String> tokens;
32:   private final Map<String, String> allTokens;
33:   private final PathBinding parent;
34: 
35:   public DefaultPathBinding(String path, String binding, Map<String, String> tokens, PathBinding parent) {
36:     this.binding = binding;
37:     this.tokens = tokens;
38:     this.parent = parent;
39: 
40:     if (parent == null) {
41:       allTokens = tokens;
42:     } else {
43:       allTokens = new LinkedHashMap<String, String>(parent.getAllTokens());
44:       allTokens.putAll(tokens);
45:     }
46: 
47:     this.bindingTerminated = binding + "/";
48: 
49:     if (path.equals(binding)) {
50:       pastBinding = "";
51:     } else if (path.startsWith(bindingTerminated)) {
52:       pastBinding = path.substring(bindingTerminated.length());
53:     } else {
54:       throw new IllegalArgumentException(String.format("Path '%s' is not a child of '%s'", path, binding));
55:     }
56:   }
57: 
58:   public String getPastBinding() {
59:     return pastBinding;
60:   }
61: 
62:   public String getBoundTo() {
63:     return binding;
64:   }
65: 
66:   public String join(String path) {
67:     return CollectionUtils.join("/", this.binding, path);
68:   }
69: 
70:   public Map<String, String> getTokens() {
71:     return tokens;
72:   }
73: 
74:   public Map<String, String> getAllTokens() {
75:     return allTokens;
76:   }
77: }
