42: import java.net.URI;
43: import java.util.concurrent.TimeUnit;
44: 
45: public class DefaultHttpClient implements HttpClient {
46:   public static final Logger LOGGER = LoggerFactory.getLogger(DefaultHttpClient.class);
47: 
48:   private ChannelPoolMap<URI, ChannelPool> channelPoolMap;
49:   private int maxContentLengthBytes;
50:   private PooledHttpConfig config;
51:   private ByteBufAllocator byteBufAllocator;
52:   private Bootstrap baseBoostrap;
53:   private ExecController execController;
54: 
55:   public DefaultHttpClient(ByteBufAllocator byteBufAllocator, int maxContentLengthBytes, ExecController execController) {
56:     this(new PooledHttpConfig(), byteBufAllocator, maxContentLengthBytes, execController);
57:   }
58: 
59:   public DefaultHttpClient(PooledHttpConfig config, ByteBufAllocator byteBufAllocator, int maxContentLengthBytes, ExecController execController) {
60:     this.config = config;
61:     this.byteBufAllocator = byteBufAllocator;
62:     this.maxContentLengthBytes = maxContentLengthBytes;
63:     this.execController = execController;
64: 
65:     baseBoostrap = new Bootstrap();
66:     baseBoostrap.option(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
67:       .channel(ChannelImplDetector.getSocketChannelImpl())
68:       .option(ChannelOption.TCP_NODELAY, true)
69:       .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, (int)TimeUnit.NANOSECONDS.toMillis(config.getConnectionTimeoutNanos()))
70:       .group(execController.getEventLoopGroup());
71: 
72:     channelPoolMap = new AbstractChannelPoolMap<URI, ChannelPool>() {
73:       @Override
74:       protected ChannelPool newPool(URI uri) {
75:         if (config.isPooled()) {
76:           return createPooledPool(uri);
77:         } else {
78:           return createNonPooledPool(uri);
79:         }
80:       }
81:     };
82:   }
83: 
84:   @Override
85:   public Promise<ReceivedResponse> get(URI uri, Action<? super RequestSpec> action) {
86:     return request(uri, action);
87:   }
88: 
89:   private static class Post implements Action<RequestSpec> {
90:     @Override
91:     public void execute(RequestSpec requestSpec) throws Exception {
92:       requestSpec.method("POST");
93:     }
94:   }
95: 
96:   @Override
97:   public Promise<ReceivedResponse> post(URI uri, Action<? super RequestSpec> action) {
98:     return request(uri, new Post().append(action));
99:   }
100: 
101:   @Override
102:   public Promise<ReceivedResponse> request(URI uri, final Action<? super RequestSpec> requestConfigurer) {
103:     return Promise.async(downstream -> new ContentAggregatingRequestAction(requestConfigurer, channelPoolMap, config, uri, this.byteBufAllocator, this.maxContentLengthBytes, Execution.current(), 0).connect(downstream));
104:   }
105: 
106:   @Override
107:   public Promise<StreamedResponse> requestStream(URI uri, Action<? super RequestSpec> requestConfigurer) {
108:     return Promise.async(downstream -> new ContentStreamingRequestAction(requestConfigurer, channelPoolMap, config, uri, this.byteBufAllocator, Execution.current(), 0).connect(downstream));
109:   }
110: 
111:   private ChannelPool createPooledPool(URI uri) {
112:     baseBoostrap.option(ChannelOption.SO_KEEPALIVE, true);
113:     ChannelPoolHandler handler = createChannelPoolHandler(uri);
114:     return new FixedChannelPool(baseBoostrap, handler, config.getMaxConnections());
115:   }
116: 
