44:   private String getCookieSessionId() {
45:     if (cookieSessionId == null) {
46:       String cookieHeader = request.headers().get("cookie");
47:       if (cookieHeader != null) {
48:         CookieTokenizer tokenizer = new CookieTokenizer();
49:         int num = tokenizer.tokenize(cookieHeader);
50:         for (int i = 0; i < num; i += 2) {
51:           String token = tokenizer.tokenAt(i);
52:           if (token.equals(COOKIE_NAME) && i < (num - 1)) {
53:             cookieSessionId = tokenizer.tokenAt(i + 1);
54:             break;
55:           }
56:         }
57:       }
58:     }
59: 
60:     return cookieSessionId;
61:   }
