1053:           down.error(e);
1054:           return;
1055:         }
1056: 
1057:         if (apply) {
1058:           try {
1059:             action.execute(value);
1060:             down.complete();
1061:           } catch (Throwable e) {
1062:             down.error(e);
1063:           }
