654:   /**
655:    * Transforms the promise failure (potentially into a value) by applying the given function to it.
656:    * <p>
657:    * If the function returns a value, the promise will now be considered successful.
658:    * <pre class="java">{@code
659:    * import ratpack.test.exec.ExecHarness;
660:    * import ratpack.exec.ExecResult;
661:    * import ratpack.exec.Promise;
662:    * import static org.junit.Assert.assertEquals;
663:    *
664:    * public class Example {
665:    *   public static void main(String... args) throws Exception {
666:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
667:    *         Promise.<String>error(new Exception("!"))
668:    *           .mapError(e -> "value")
669:    *     );
670:    *
671:    *     assertEquals("value", result.getValue());
672:    *   }
673:    * }
674:    * }</pre>
675:    * <p>
676:    * If the function throws an exception, that exception will now represent the promise failure.
677:    * <pre class="java">{@code
678:    * import ratpack.test.exec.ExecHarness;
679:    * import ratpack.exec.ExecResult;
680:    * import ratpack.exec.Promise;
681:    * import static org.junit.Assert.assertEquals;
682:    *
683:    * public class Example {
684:    *   public static void main(String... args) throws Exception {
685:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
686:    *         Promise.<String>error(new Exception("!"))
687:    *           .mapError(e -> { throw new RuntimeException("mapped", e); })
688:    *     );
689:    *
690:    *     assertEquals("mapped", result.getThrowable().getMessage());
691:    *   }
692:    * }
693:    * }</pre>
694:    * <p>
695:    * The function will not be called if the promise is successful.
696:    *
697:    * @param transformer the transformation to apply to the promise failure
698:    * @return a promise
699:    */
700:   default Promise<T> mapError(Function<? super Throwable, ? extends T> transformer) {
701:     return transform(up -> down ->
702:       up.connect(down.onError(throwable -> {
703:         try {
704:           T transformed = transformer.apply(throwable);
705:           down.success(transformed);
706:         } catch (Throwable t) {
707:           down.error(t);
708:         }
709:       }))
710:     );
711:   }
712: 
713:   /**
714:    * Transforms a failure of the given type (potentially into a value) by applying the given function to it.
715:    * <p>
716:    * This method is similar to {@link #mapError(Function)}, except that it will only apply if the error is of the given type.
717:    * If the error is not of the given type, it will not be transformed and will propagate as normal.
718:    *
719:    * @param function the transformation to apply to the promise failure
720:    * @return a promise
721:    * @since 1.3
722:    */
723:   default <E extends Throwable> Promise<T> mapError(Class<E> type, Function<? super Throwable, ? extends T> transformer) {
724:     return transform(up -> down ->
725:       up.connect(down.onError(throwable -> {
726:         if (type.isInstance(throwable)) {
727:           T transformed;
728:           try {
729:             transformed = transformer.apply(throwable);
730:           } catch (Throwable t) {
731:             down.error(t);
732:             return;
733:           }
734:           down.success(transformed);
735:         } else {
736:           down.error(throwable);
737:         }
738:       }))
739:     );
740:   }
