766:   /**
767:    * Transforms a failure of the given type (potentially into a value) by applying the given function to it.
768:    * <p>
769:    * This method is similar to {@link #mapError(Class, Function)}, except that it allows async transformation.
770:    *
771:    * @param function the transformation to apply to the promise failure
772:    * @return a promise
773:    * @since 1.3
774:    */
775:   default <E extends Throwable> Promise<T> flatMapError(Class<E> type, Function<? super E, ? extends Promise<T>> function) {
776:     return transform(up -> down ->
777:       up.connect(down.onError(throwable -> {
778:         if (type.isInstance(throwable)) {
779:           Promise<T> transformed;
780:           try {
781:             transformed = function.apply(type.cast(throwable));
782:           } catch (Throwable t) {
783:             down.error(t);
784:             return;
785:           }
786:           transformed.connect(down);
787:         } else {
788:           down.error(throwable);
789:         }
790:       }))
791:     );
792:   }
