976:    * <pre class="java">{@code
977:    * import com.google.common.collect.Lists;
978:    * import ratpack.test.exec.ExecHarness;
979:    * import ratpack.exec.ExecResult;
980:    * import ratpack.exec.Promise;
981:    *
982:    * import java.util.List;
983:    *
984:    * import static org.junit.Assert.*;
985:    *
986:    * public class Example {
987:    *   public static ExecResult<Integer> yield(int i, List<Integer> collector) throws Exception {
988:    *     return ExecHarness.yieldSingle(c ->
989:    *         Promise.value(i)
990:    *           .route(v -> v > 5, collector::add)
991:    *     );
992:    *   }
993:    *
994:    *   public static void main(String... args) throws Exception {
995:    *     List<Integer> routed = Lists.newLinkedList();
996:    *
997:    *     ExecResult<Integer> result1 = yield(1, routed);
998:    *     assertEquals(new Integer(1), result1.getValue());
999:    *     assertFalse(result1.isComplete()); // false because promise returned a value before the execution completed
1000:    *     assertTrue(routed.isEmpty());
1001:    *
1002:    *     ExecResult<Integer> result10 = yield(10, routed);
1003:    *     assertNull(result10.getValue());
1004:    *     assertTrue(result10.isComplete()); // true because the execution completed before the promised value was returned (i.e. it was routed)
1005:    *     assertTrue(routed.contains(10));
1006:    *   }
1007:    * }
1008:    * }</pre>
1009:    * <p>
1010:    * Be careful about using this where the eventual promise subscriber is unlikely to know that the promise
1011:    * will routed as it can be surprising when neither the promised value nor an error appears.
1012:    * <p>
1013:    * It can be useful at the handler layer to provide common validation.
1014:    * <pre class="java">{@code
1015:    * import ratpack.exec.Promise;
1016:    * import ratpack.handling.Context;
1017:    * import ratpack.test.embed.EmbeddedApp;
1018:    *
1019:    * import static org.junit.Assert.assertEquals;
1020:    *
1021:    * public class Example {
1022:    *   public static Promise<Integer> getAge(Context ctx) {
1023:    *     return Promise.value(10)
1024:    *       .route(
1025:    *         i -> i < 21,
1026:    *         i -> ctx.render(i + " is too young to be here!")
1027:    *       );
1028:    *   }
1029:    *
1030:    *   public static void main(String... args) throws Exception {
1031:    *     EmbeddedApp.fromHandler(ctx ->
1032:    *         getAge(ctx).then(age -> ctx.render("welcome!"))
1033:    *     ).test(httpClient -> {
1034:    *       assertEquals("10 is too young to be here!", httpClient.getText());
1035:    *     });
1036:    *   }
1037:    * }
1038:    * }</pre>
1039:    * <p>
1040:    * If the routed-to action throws an exception, it will be forwarded down the promise chain.
1041:    *
