902:    *
903:    *   public static void main(String... args) throws Exception {
904:    *     ExecHarness.runSingle(e ->
905:    *         Promise.value("foo")
906:    *           .to(RxRatpack::observe)
907:    *           .doOnNext(i -> LOG.add("doOnNext"))
