1315:   /**
1316:    * Emits the time taken from when the promise is subscribed to to when the result is available.
1317:    * <p>
1318:    * The given {@code action} is called regardless of whether the promise is successful or not.
1319:    * <p>
1320:    * If the promise fails and this method throws an exception, the original exception will propagate with the thrown exception suppressed.
1321:    * If the promise succeeds and this method throws an exception, the thrown exception will propagate.
1322:    *
1323:    * @param action a callback for the time
1324:    * @since 1.3
1325:    * @return effectively {@code this}
1326:    */
1327:   default Promise<T> time(Action<? super Duration> action) {
1328:     return transform(up -> down -> {
1329:       long start = System.nanoTime();
1330:       up.connect(new Downstream<T>() {
1331:         private Duration duration() {
1332:           // protect against clock skew causing negative durations
1333:           return Duration.ofNanos(Math.max(0, System.nanoTime() - start));
1334:         }
1335: 
1336:         @Override
1337:         public void success(T value) {
1338:           try {
1339:             action.execute(duration());
1340:           } catch (Throwable t) {
1341:             down.error(t);
1342:             return;
1343:           }
1344:           down.success(value);
1345:         }
1346: 
1347:         @Override
1348:         public void error(Throwable throwable) {
1349:           try {
1350:             action.execute(duration());
1351:           } catch (Throwable t) {
1352:             throwable.addSuppressed(t);
1353:           }
1354:           down.error(throwable);
1355:         }
1356: 
1357:         @Override
1358:         public void complete() {
1359:           try {
1360:             action.execute(duration());
1361:           } catch (Throwable t) {
1362:             down.error(t);
