44:   @Override
45:   public <T> SuccessOrErrorPromise<T> exec(final Callable<T> operation) {
46:     final Context context = contextStorage.get();
47:     final FinishedOnThreadCallbackManager finishedOnThreadCallbackManager = context.get(FinishedOnThreadCallbackManager.class);
48:     return context.promise(new Action<Fulfiller<? super T>>() {
49:       @Override
50:       public void execute(final Fulfiller<? super T> fulfiller) throws Exception {
51:         finishedOnThreadCallbackManager.register(new Runnable() {
52:           @Override
53:           public void run() {
54:             List<ProcessingInterceptor> interceptors = context.getAll(ProcessingInterceptor.class);
55:             ListenableFuture<T> future = backgroundExecutor.submit(new BackgroundOperation(interceptors));
56:             Futures.addCallback(future, new ForegroundResume(interceptors, fulfiller), foregroundExecutor);
57:           }
58:         });
59:       }
