61:       class BackgroundOperation extends InterceptedOperation implements Callable<T> {
62:         private Exception exception;
63:         private T result;
64: 
65:         public BackgroundOperation(List<ProcessingInterceptor> interceptors) {
66:           super(ProcessingInterceptor.Type.BACKGROUND, interceptors, context);
67:         }
68: 
69:         @Override
70:         public T call() throws Exception {
71:           contextStorage.set(context);
72:           try {
73:             run();
74:             if (exception != null) {
75:               throw exception;
76:             } else {
77:               return result;
78:             }
79:           } finally {
80:             contextStorage.remove();
81:           }
82:         }
