17: package ratpack.pac4j.internal;
18: 
19: import com.google.common.collect.ImmutableList;
20: import org.pac4j.core.client.Client;
21: import org.pac4j.core.client.Clients;
22: import org.pac4j.core.context.WebContext;
23: import org.pac4j.core.credentials.Credentials;
24: import org.pac4j.core.exception.RequiresHttpAction;
25: import org.pac4j.core.exception.TechnicalException;
26: import org.pac4j.core.profile.UserProfile;
27: import ratpack.handling.Context;
28: import ratpack.handling.Handler;
29: import ratpack.path.PathBinding;
30: import ratpack.registry.Registries;
31: import ratpack.registry.Registry;
32: import ratpack.server.PublicAddress;
33: import ratpack.session.Session;
34: import ratpack.util.Types;
35: 
36: import java.util.List;
37: import java.util.Optional;
38: 
39: public class Pac4jCallbackHandler implements Handler {
40: 
41:   private final String path;
42:   private final ImmutableList<Client<?, ?>> clients;
43: 
44:   public Pac4jCallbackHandler(String path, List<Client<?, ?>> clients) {
45:     this.path = path;
46:     this.clients = ImmutableList.copyOf(clients);
47:   }
48: 
49:   @Override
50:   public void handle(Context ctx) throws Exception {
51:     PathBinding pathBinding = ctx.get(PathBinding.class);
52:     String boundTo = pathBinding.getBoundTo();
53:     String pastBinding = pathBinding.getPastBinding();
54:     PublicAddress publicAddress = ctx.get(PublicAddress.class);
55:     String absoluteCallbackUrl = publicAddress.getAddress(ctx) + boundTo + "/" + path;
56: 
57:     @SuppressWarnings("rawtypes")
58:     List<Client> cast = Types.cast(this.clients);
59:     Clients clients = new Clients(absoluteCallbackUrl, cast);
60: 
61:     if (pastBinding.equals(path)) {
62:       ctx.get(Session.class).getData().then(sessionData -> {
63:         RatpackWebContext webContext = new RatpackWebContext(ctx, sessionData);
64:         try {
65:           Client<?, ?> client = clients.findClient(webContext);
66:           UserProfile profile = getProfile(webContext, client);
67:           if (profile != null) {
68:             sessionData.set(Pac4jSessionKeys.USER_PROFILE, profile);
69:           }
70:           Optional<String> originalUrl = sessionData.get(Pac4jSessionKeys.REQUESTED_URL);
71:           sessionData.remove(Pac4jSessionKeys.REQUESTED_URL);
72:           ctx.redirect(originalUrl.orElse("/"));
73:         } catch (Exception e) {
74:           if (e instanceof RequiresHttpAction) {
75:             webContext.sendResponse((RequiresHttpAction) e);
76:           } else {
77:             ctx.error(new TechnicalException("Failed to get user profile", e));
78:           }
79:         }
80:       });
81:     } else {
82:       Registry registry = Registries.just(Clients.class, clients);
83:       ctx.next(registry);
84:     }
85:   }
86: 
87:   private <C extends Credentials, U extends UserProfile> UserProfile getProfile(WebContext webContext, Client<C, U> client) throws RequiresHttpAction {
88:     C credentials = client.getCredentials(webContext);
89:     return client.getUserProfile(credentials, webContext);
90:   }
91: 
92: }
