66:    * The value is determined by: {@code globalProperties.getProperty(SYSPROP_PREFIX_PROPERTY, SYSPROP_PREFIX_DEFAULT)}
67:    *
68:    * @param classLoader The classloader to use to find the properties file.
69:    * @param globalProperties The environmental (override) properties
70:    * @param defaultProperties The default properties to use when a property is omitted
71:    * @return A launch config
72:    */
73:   public static LaunchConfig createFromGlobalProperties(ClassLoader classLoader, Properties globalProperties, Properties defaultProperties) {
74:     String propertyPrefix = globalProperties.getProperty(SYSPROP_PREFIX_PROPERTY, SYSPROP_PREFIX_DEFAULT);
75:     return createFromGlobalProperties(classLoader, propertyPrefix, globalProperties, defaultProperties);
76:   }
