388:     public void intercept(final ExecInterceptor.ExecType execType, final List<ExecInterceptor> interceptors, final Action<? super Execution> action) throws Exception {
389:       new InterceptedOperation(execType, interceptors) {
390:         @Override
391:         protected void performOperation() throws Exception {
392:           action.execute(Execution.this);
393:         }
394:       }.run();
395:     }
