195:     private static void doApp(RatpackServerSpec definition, boolean staticCompile, Path baseDir, Path scriptFile) throws Exception {
196:       String script = IoUtils.read(UnpooledByteBufAllocator.DEFAULT, scriptFile).toString(CharsetUtil.UTF_8);
197: 
198:       RatpackDslClosures closures = new RatpackDslScriptCapture(staticCompile, RatpackDslBacking::new).apply(scriptFile, script);
199:       definition.serverConfig(ClosureUtil.configureDelegateFirstAndReturn(loadPropsIfPresent(ServerConfig.builder().baseDir(baseDir), baseDir), closures.getServerConfig()));
200: 
201:       definition.registry(r -> {
202:         return Guice.registry(bindingsSpec -> {
203:           bindingsSpec.bindInstance(new FileBackedReloadInformant(scriptFile));
204:           ClosureUtil.configureDelegateFirst(bindingsSpec, closures.getBindings());
205:         }).apply(r);
206:       });
207: 
208:       definition.handler(r -> {
209:         return Groovy.chain(r, closures.getHandlers());
210:       });
211:     }
212: 
213:     private static ServerConfigBuilder loadPropsIfPresent(ServerConfigBuilder serverConfigBuilder, Path baseDir) {
214:       Path propsFile = baseDir.resolve(BaseDir.DEFAULT_BASE_DIR_MARKER_FILE_PATH);
215:       if (Files.exists(propsFile)) {
216:         serverConfigBuilder.props(propsFile);
217:       }
218:       return serverConfigBuilder;
219:     }
