41: public class DefaultExecController implements ExecController {
42: 
43:   private static final ThreadLocal<ExecController> THREAD_BINDING = new ThreadLocal<>();
44: 
45:   private final static Logger LOGGER = LoggerFactory.getLogger(DefaultExecController.class);
46: 
47:   private final ThreadLocal<Execution> executionHolder = new ThreadLocal<>();
48: 
49:   private final ListeningScheduledExecutorService computeExecutor;
50:   private final ListeningExecutorService blockingExecutor;
51:   private final EventLoopGroup eventLoopGroup;
52:   private final ExecControl control;
53:   private final int numThreads;
54: 
55:   public DefaultExecController(int numThreads) {
56:     this.numThreads = numThreads;
57:     this.eventLoopGroup = new NioEventLoopGroup(numThreads, new ExecControllerBindingThreadFactory("ratpack-compute", Thread.MAX_PRIORITY));
58:     this.computeExecutor = MoreExecutors.listeningDecorator(eventLoopGroup);
59:     this.blockingExecutor = MoreExecutors.listeningDecorator(Executors.newCachedThreadPool(new ExecControllerBindingThreadFactory("ratpack-blocking", Thread.NORM_PRIORITY)));
60:     this.control = new FactoryBackedExecControl();
61:   }
62: 
63:   public static Optional<ExecController> getThreadBoundController() {
64:     return Optional.fromNullable(THREAD_BINDING.get());
65:   }
66: 
67:   public void close() {
68:     eventLoopGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS);
69:     blockingExecutor.shutdown();
70:   }
71: 
72:   @Override
73:   public Execution getExecution() throws ExecutionException {
74:     Execution execution = executionHolder.get();
75:     if (execution == null) {
76:       throw new ExecutionException("No execution is bound to the current thread (i.e. you are not on a Ratpack managed thread)");
77:     } else {
78:       return execution;
79:     }
80:   }
