92:   @Override
93:   public void start(final Action<? super ratpack.exec.Execution> action) {
94:     if (!isManagedThread() || executionHolder.get() != null) {
95:       computeExecutor.submit(new Runnable() {
96:         @Override
97:         public void run() {
98:           start(action);
99:         }
100:       });
101:     } else {
102:       new Execution(action);
103:     }
104:   }
