106:   private class FactoryBackedExecControl implements ExecControl {
107: 
108:     private final Factory<Execution> executionFactory = new Factory<Execution>() {
109:       @Override
110:       public Execution create() {
111:         return getExecution();
112:       }
113:     };
114: 
115:     @Override
116:     public <T> Promise<T> blocking(final Callable<T> blockingOperation) {
117:       return promise(new Action<Fulfiller<? super T>>() {
118:         @Override
119:         public void execute(final Fulfiller<? super T> fulfiller) throws Exception {
120:           final Execution execution = getExecution();
121:           ListenableFuture<T> future = blockingExecutor.submit(new BlockingOperation(execution));
122:           Futures.addCallback(future, new ComputeResume(fulfiller), computeExecutor);
123:         }
124: 
125:         class BlockingOperation implements Callable<T> {
126:           private final Execution execution;
127:           private Exception exception;
128:           private T result;
129: 
130:           public BlockingOperation(Execution execution) {
131:             this.execution = execution;
132:           }
133: 
134:           @Override
135:           public T call() throws Exception {
136:             execution.intercept(ExecInterceptor.ExecType.BLOCKING, execution.interceptors, new Action<Execution>() {
137:               @Override
138:               public void execute(Execution execution) throws Exception {
139:                 try {
140:                   result = blockingOperation.call();
141:                 } catch (Exception e) {
142:                   exception = e;
143:                 }
144:               }
145:             });
146: 
147:             if (exception != null) {
148:               throw exception;
149:             } else {
150:               return result;
151:             }
152:           }
153:         }
154: 
155:         class ComputeResume implements FutureCallback<T> {
156:           private final Fulfiller<? super T> fulfiller;
157: 
158:           public ComputeResume(Fulfiller<? super T> fulfiller) {
159:             this.fulfiller = fulfiller;
160:           }
161: 
162:           @Override
163:           public void onSuccess(final T result) {
164:             fulfiller.success(result);
165:           }
166: 
167:           @SuppressWarnings("NullableProblems")
168:           @Override
169:           public void onFailure(final Throwable t) {
170:             fulfiller.error(t);
171:           }
172:         }
173:       });
