175:     }
176: 
177:     @Override
178:     public <T> Promise<T> promise(Action<? super Fulfiller<T>> action) {
179:       return new DefaultPromise<>(executionFactory, action);
180:     }
181: 
182:     @Override
183:     public void fork(Action<? super ratpack.exec.Execution> action) {
