28: public class MulticastPublisher<T> implements Publisher<T> {
29: 
30:   private final ConcurrentLinkedDeque<Subscriber<? super T>> throttledSubscribers = new ConcurrentLinkedDeque<>();
31:   private final Publisher<T> upstreamPublisher;
32:   private final AtomicBoolean requestedUpstream;
33:   private final AtomicBoolean upstreamFinished;
34: 
35:   public MulticastPublisher(Publisher<T> publisher) {
36:     this.upstreamPublisher = publisher;
37:     this.requestedUpstream = new AtomicBoolean();
38:     this.upstreamFinished = new AtomicBoolean();
39:   }
40: 
41:   @Override
42:   public void subscribe(final Subscriber<? super T> downStreamSubscriber) {
43:     if (upstreamFinished.get()) {
44:       downStreamSubscriber.onError(new IllegalStateException("The upstream publisher has completed, either successfully or with error.  No further subscriptions will be accepted"));
45:     } else {
46:       throttle(new Publisher<T>() {
47:         @Override
48:         public void subscribe(final Subscriber<? super T> s) {
49:           s.onSubscribe(new Subscription() {
50:             @Override
51:             public void request(long n) {
52:               throttledSubscribers.add(s);
53:               tryUpstreamSubscribe();
54:             }
55: 
56:             @Override
57:             public void cancel() {
58:               // throttle will deal with cancelling this subscription if the downstream subscriber cancels or throws an exception.
59:               // The downstream subscriber will be "unsubscribed" from this publisher.
60:               throttledSubscribers.remove(s);
61:             }
62:           });
63:         }
64:       }).subscribe(downStreamSubscriber);
65:     }
66:   }
