68:   private void tryUpstreamSubscribe() {
69:     if (requestedUpstream.compareAndSet(false, true)) {
70:       this.upstreamPublisher.subscribe(new Subscriber<T>() {
71:         Subscription subscription;
72: 
73:         @Override
74:         public void onSubscribe(Subscription s) {
75:           this.subscription = s;
76:           this.subscription.request(Long.MAX_VALUE);
77:         }
78: 
