99:    * Registry parent = registry().add(Thing.class, new ThingImpl("parent-1")).add(Thing.class, new ThingImpl("parent-2")).build();
100:    * Registry joined = join(parent, child);
101:    *
102:    * assert joined.get(Thing.class).getName() == "child-1";
103:    *
104:    * List&lt;Thing&gt; all = joined.getAll(Thing.class);
105:    * assert all.get(0).getName() == "child-1";
106:    * assert all.get(1).getName() == "child-2";
107:    * assert all.get(2).getName() == "parent-1";
108:    * assert all.get(3).getName() == "parent-2";
