330:   /**
331:    * Adds a handler that delegates to the given handler if
332:    * the relative {@code path} matches the given {@code path} and the {@code request} {@code HTTPMethod}
333:    * is {@code DELETE}.
334:    *
335:    * @param path the relative path to match on
336:    * @param handler the handler to delegate to
337:    * @return this
338:    * @see Chain#get(String, Handler)
339:    * @see Chain#post(String, Handler)
340:    * @see Chain#put(String, Handler)
341:    * @see Chain#patch(String, Handler)
342:    * @see Chain#path(String, Handler)
343:    */
344:   default Chain delete(String path, Handler handler) {
345:     return all(Handlers.path(path, Handlers.chain(Handlers.delete(), handler)));
346:   }
347: 
348:   default Chain delete(String path, Class<? extends Handler> handler) {
349:     return delete(path, getRegistry().get(handler));
