512:   /**
513:    * Adds a handler to the chain that delegates to the given handler chain if the request has a {@code Host} header that matches the given value exactly.
514:    *
515:    * <pre class="java-chain-dsl">{@code
516:    *  chain.
517:    *    host("foo.com", new Action<Chain>() {
518:    *      public void execute(Chain hostChain) {
519:    *        hostChain.all(new Handler() {
520:    *          public void handle(Context context) {
521:    *            context.getResponse().send("Host Handler");
522:    *          }
523:    *        });
524:    *      }
525:    *    });
526:    * }</pre>
527:    *
528:    * @param hostName the name of the HTTP Header to match on
529:    * @param action the handler chain to delegate to if the host matches
530:    * @return this
531:    * @throws Exception any thrown by {@code action}
532:    */
533:   default Chain host(String hostName, Action<? super Chain> action) throws Exception {
534:     return when(ctx ->
535:         Optional.ofNullable(ctx.getRequest().getHeaders().get(HttpHeaderNames.HOST))
536:           .map(s -> s.equals(hostName))
537:           .orElse(false),
538:       action
539:     );
540:   }
541: 
542:   default Chain host(String hostName, Class<? extends Action<? super Chain>> action) throws Exception {
543:     return host(hostName, getRegistry().get(action));
544:   }
545: 
546:   /**
