29: /**
30:  * Builder for Pac4J callback handler.
31:  */
32: public class Pac4jCallbackHandlerBuilder {
33: 
34:   private BiFunction<Context, RatpackWebContext, Client<Credentials, UserProfile>> findClientFunction;
35:   private BiConsumer<Context, UserProfile> onSuccess;
36:   private BiConsumer<Context, Throwable> onError;
37: 
38:   public Pac4jCallbackHandler build() {
39:     return new Pac4jCallbackHandler(findClientFunction, onSuccess, onError);
40:   }
