67:    * builder.handleProfile(((context, profile) -&gt; context.next(Registries.just(profile))));
68:    * </code>
69:    * </pre>
70:    *
71:    * @param onSuccess the handler function
72:    * @return the builder
73:    */
74:   @SuppressWarnings("unused")
75:   public Pac4jCallbackHandlerBuilder handleProfile(BiConsumer<Context, UserProfile> onSuccess) {
76:     this.onSuccess = onSuccess;
77:     return this;
78:   }
79: 
