31: import java.util.*;
32: import java.util.concurrent.ConcurrentHashMap;
33: import java.util.concurrent.ConcurrentMap;
34: 
35: public class DefaultClientSessionService implements SessionService {
36: 
37:   private static final Base64.Encoder ENCODER = Base64.getUrlEncoder();
38:   private static final Base64.Decoder DECODER = Base64.getUrlDecoder();
39:   private static final Escaper ESCAPER = UrlEscapers.urlFormParameterEscaper();
40: 
41:   private static final ByteBuf EQUALS = Unpooled.unreleasableBuffer(ByteBufUtil.encodeString(UnpooledByteBufAllocator.DEFAULT, CharBuffer.wrap("="), CharsetUtil.UTF_8));
42:   private static final ByteBuf AMPERSAND = Unpooled.unreleasableBuffer(ByteBufUtil.encodeString(UnpooledByteBufAllocator.DEFAULT, CharBuffer.wrap("&"), CharsetUtil.UTF_8));
43: 
44:   private static final String SESSION_SEPARATOR = ":";
45: 
46:   private final Signer signer;
47:   private final Crypto crypto;
48: 
49:   public DefaultClientSessionService(Signer signer, Crypto crypto) {
50:     this.signer = signer;
51:     this.crypto = crypto;
52:   }
53: 
54:   @Override
55:   public String[] serializeSession(ByteBufAllocator bufferAllocator, Set<Map.Entry<String, Object>> entries, int maxCookieSize) {
56:     String serializedSession = serializeSession(bufferAllocator, entries);
57:     int sessionSize = serializedSession.length();
58:     if (sessionSize <= maxCookieSize) {
59:       return new String[] {serializedSession};
60:     }
61:     int numOfPartitions = (int) Math.ceil((double)sessionSize / maxCookieSize);
62:     String[] partitions = new String[numOfPartitions];
63:     for (int i = 0; i < numOfPartitions; i++) {
64:       int from = i * maxCookieSize;
65:       int to = Math.min(from + maxCookieSize, sessionSize - 1);
66:       partitions[i] = serializedSession.substring(from, to);
67:     }
68:     return partitions;
69:   }
70: 
71:   @Override
72:   public String serializeSession(ByteBufAllocator bufferAllocator, Set<Map.Entry<String, Object>> entries) {
73:     ByteBuf[] buffers = new ByteBuf[3 * entries.size() + entries.size() - 1];
74:     try {
75:       int i = 0;
76: 
77:       for (Map.Entry<String, Object> entry : entries) {
78:         buffers[i++] = encode(bufferAllocator, entry.getKey());
79:         buffers[i++] = EQUALS;
80:         buffers[i++] = encode(bufferAllocator, entry.getValue().toString());
81: 
82:         if (i < buffers.length) {
83:           buffers[i++] = AMPERSAND;
84:         }
85:       }
86: 
87:       ByteBuf payloadBuffer = Unpooled.wrappedBuffer(buffers.length, buffers);
88:       byte[] payloadBytes = new byte[payloadBuffer.readableBytes()];
89:       payloadBuffer.getBytes(0, payloadBytes);
90:       if (crypto != null) {
91:         payloadBytes = crypto.encrypt(payloadBuffer);
92:         payloadBuffer = Unpooled.wrappedBuffer(payloadBytes);
93:       }
94: 
95:       String payloadString = ENCODER.encodeToString(payloadBytes);
96: 
97:       byte[] digest = signer.sign(payloadBuffer);
98:       String digestString = ENCODER.encodeToString(digest);
99: 
100:       return payloadString + SESSION_SEPARATOR + digestString;
101: 
102:     } finally {
103:       for (ByteBuf buffer : buffers) {
104:         if (buffer != null) {
105:           buffer.release();
106:         }
107:       }
108:     }
109:   }
110: 
111:   private ByteBuf encode(ByteBufAllocator bufferAllocator, String value) {
112:     String escaped = ESCAPER.escape(value);
113:     return ByteBufUtil.encodeString(bufferAllocator, CharBuffer.wrap(escaped), CharsetUtil.UTF_8);
114:   }
115: 
116:   @Override
117:   public ConcurrentMap<String, Object> deserializeSession(Cookie[] sessionCookies) {
118:     // assume table is sorted
119:     StringBuilder sb = new StringBuilder();
120:     for (int i = 0; i < sessionCookies.length; i++) {
121:       sb.append(sessionCookies[i].value());
122:     }
123:     return deserializeSession(sb.toString());
124:   }
125: 
126:   private ConcurrentMap<String, Object> deserializeSession(String cookieValue) {
127:     ConcurrentMap<String, Object> sessionStorage = new ConcurrentHashMap<>();
128: 
129:     String encodedPairs = cookieValue;
130:     if (encodedPairs != null) {
131:       String[] parts = encodedPairs.split(SESSION_SEPARATOR);
132:       if (parts.length == 2) {
133:         byte[] urlEncoded = DECODER.decode(parts[0]);
134:         byte[] digest = DECODER.decode(parts[1]);
135: 
136:         try {
137:           byte[] expectedDigest = signer.sign(Unpooled.wrappedBuffer(urlEncoded));
138: 
139:           if (Arrays.equals(digest, expectedDigest)) {
140:             byte[] message;
141:             if (crypto == null) {
142:               message = urlEncoded;
143:             } else {
144:               message = crypto.decrypt(Unpooled.wrappedBuffer(urlEncoded));
145:             }
146: 
147:             String payload = new String(message, CharsetUtil.UTF_8);
148:             QueryStringDecoder queryStringDecoder = new QueryStringDecoder(payload, CharsetUtil.UTF_8, false);
149:             Map<String, List<String>> decoded = queryStringDecoder.parameters();
150:             for (Map.Entry<String, List<String>> entry : decoded.entrySet()) {
151:               String value = entry.getValue().isEmpty() ? null : entry.getValue().get(0);
152:               sessionStorage.put(entry.getKey(), value);
153:             }
154:           }
155:         } catch (Exception e) {
156:           throw Exceptions.uncheck(e);
157:         }
158:       }
159:     }
160: 
161:     return sessionStorage;
162:   }
163: }
