299:     } catch (Exception errorHandlerException) {
300:       StringWriter stringWriter = new StringWriter();
301:       PrintWriter printWriter = new PrintWriter(stringWriter);
302:       stringWriter.
303:         append("Exception thrown by error handler ").
304:         append(serverErrorHandler.toString()).
305:         append(" while handling exception\nOriginal exception: ");
306:       unpacked.printStackTrace(printWriter);
307:       stringWriter.
308:         append("Error handler exception: ");
309:       errorHandlerException.printStackTrace(printWriter);
310:       LOGGER.warning(stringWriter.toString());
311:       requestConstants.response.status(500).send();
312:     }
313:   }
