349:     return new ResultAction<T>() {
350:       @Override
351:       public void execute(Result<T> result) {
352:         if (result.isFailure()) {
353:           dispatchException(result.getFailure());
354:         } else {
355:           try {
356:             action.execute(result.getValue());
357:           } catch (Exception e) {
358:             dispatchException(e);
359:           }
360:         }
361:       }
362:     };
363:   }
