27: /**
28:  * A handler implementation that collects {@link Timer} metrics for a {@link Request}.
29:  * <p>
30:  * Metrics are grouped by {@link ratpack.http.Request#getUri()} and {@link ratpack.http.Request#getMethod()}.
31:  * For example, the following requests...
32:  *
33:  * <pre>
34:  * /
35:  * /book
36:  * /author/1/books
37:  * /js/jquery.min.js
38:  * /css/bootstrap.min.css
39:  * </pre>
40:  *
41:  * will be reported as...
42:  *
43:  * <pre>
44:  * [root]~GET~Request
45:  * [book]~GET~Request
46:  * [author][1][books]~GET~Request
47:  * [js][jquery.min.js]~GET~Request
48:  * [css][bootstrap.min.css]~GET~Request
49:  * </pre>
50:  *
51:  */
52: public class RequestTimingHandler implements Handler {
53: 
54:   private final Handler rest;
55: 
56:   public RequestTimingHandler(Handler rest) {
57:     this.rest = rest;
58:   }
59: 
60:   @Override
61:   public void handle(final Context context) throws Exception {
62:     final MetricRegistry metricRegistry = context.get(MetricRegistry.class);
63:     final Request request = context.getRequest();
64:     BackgroundExecTimingInterceptor backgroundExecTimingInterceptor = new BackgroundExecTimingInterceptor(metricRegistry, request);
65: 
66:     context.addExecInterceptor(backgroundExecTimingInterceptor, new Action<Context>() {
67:       @Override
68:       public void execute(Context context) throws Exception {
69:         String tag = buildRequestTimerTag(request.getUri(), request.getMethod().getName());
70:         final Timer.Context timer = metricRegistry.timer(tag).time();
71:         context.onClose(new Action<RequestOutcome>() {
72:           public void execute(RequestOutcome thing) throws Exception {
73:             timer.stop();
74:           }
75:         });
76:         context.insert(rest);
77:       }
78:     });
79:   }
80: 
81:   private String buildRequestTimerTag(String requestUri, String requestMethod) {
82:     return (requestUri.equals("/") ? "[root" : requestUri.replaceFirst("/", "[").replace("/", "][")) + "]~" + requestMethod + "~Request";
83:   }
84: 
85: }
