261:    * @param <T>     the type of value promised
262:    * @return a single for the promised value
263:    */
264:   public static <T> Single<T> single(Promise<T> promise) {
265:     return Single.create(subscriber ->
266:       promise.onError(subscriber::onError).then(subscriber::onSuccess)
267:     );
268:   }
