302:   public static <T> Maybe<T> maybe(Promise<T> promise) {
303:     return Maybe.create(subscriber ->
304:       promise.onError(subscriber::onError).then(value -> {
305:         subscriber.onSuccess(value);
306:         subscriber.onComplete();
307:       })
308:     );
