792:   /**
793:    * A variant of {@link #fork} that allows access to the registry of the forked execution inside an {@link Action}.
794:    * <p>
795:    * This allows the insertion of objects via {@link RegistrySpec#add} that will be available to the forked observable.
796:    * <p>
797:    * You do not have access to the original execution inside the {@link Action}.
798:    * <p>
799:    * <pre class="java">{@code
800:    * import ratpack.exec.Execution;
801:    * import ratpack.registry.RegistrySpec;
802:    * import ratpack.rx2.RxRatpack;
803:    * import ratpack.test.exec.ExecHarness;
804:    *
805:    * import io.reactivex.Observable;
806:    *
807:    * import static org.junit.Assert.assertEquals;
808:    *
809:    * public class Example {
810:    *   public static void main(String[] args) throws Exception {
811:    *     RxRatpack.initialize();
812:    *
813:    *     try (ExecHarness execHarness = ExecHarness.harness(6)) {
814:    *       String concatenatedResult = execHarness.yield(execution -> {
815:    *
816:    *         Observable<String> notYetForked = Observable.just("foo")
817:    *           .map((value) -> value + Execution.current().get(String.class));
818:    *
819:    *         Observable<String> forkedObservable = RxRatpack.fork(
820:    *           notYetForked,
821:    *           (RegistrySpec registrySpec) -> registrySpec.add("bar")
822:    *         );
823:    *
824:    *         return RxRatpack.promiseSingle(forkedObservable);
825:    *       }).getValueOrThrow();
826:    *
827:    *       assertEquals(concatenatedResult, "foobar");
828:    *     }
829:    *   }
830:    * }
831:    * }</pre>
832:    *
833:    * @param observable         the observable sequence to execute on a different compute thread
834:    * @param registrySpec an Action where objects can be inserted into the registry of the forked execution
835:    * @param <T>                the element type
836:    * @return an observable on the compute thread that <code>fork</code> was called from
837:    * @throws Exception
838:    * @see #fork(Observable)
839:    */
840:   public static <T> Observable<T> fork(Observable<T> observable, Action<? super RegistrySpec> registrySpec) throws Exception {
841:     return observeEach(promise(observable).fork(execSpec -> execSpec.register(registrySpec)));
