706:    *       new Thread(() -> {
707:    *         subscriber.onNext("foo");
708:    *         subscriber.onNext("bar");
709:    *         subscriber.onComplete();
710:    *       }).start()
711:    *     );
712:    *
713:    *     List<String> strings = ExecHarness.yieldSingle(e ->
714:    *       RxRatpack.promise(asyncObservable.compose(RxRatpack::bindExec))
715:    *     ).getValue();
716:    *
717:    *     assertEquals(Arrays.asList("foo", "bar"), strings);
718:    *   }
719:    * }
720:    * }</pre>
721:    * <p>
722:    *
723:    * @param source the observable source
724:    * @param <T>    the type of item observed
