35:   public DefaultPathContext(String path, String binding, Map<String, String> tokens, PathContext parent) {
36:     this.binding = binding;
37:     this.tokens = tokens;
38:     this.parent = parent;
39: 
40:     if (parent == null) {
41:       allTokens = tokens;
