44:       allTokens.putAll(tokens);
45:     }
46: 
47:     this.bindingTerminated = binding + "/";
48: 
49:     if (path.equals(binding)) {
50:       pastBinding = "";
51:     } else if (path.startsWith(bindingTerminated)) {
52:       pastBinding = path.substring(bindingTerminated.length());
53:     } else {
54:       throw new IllegalArgumentException(String.format("Path '%s' is not a child of '%s'", path, binding));
55:     }
56:   }
