68:   @Override
69:   public void transmit(Background execContext, final BasicFileAttributes basicFileAttributes, final Path file) throws Exception {
70:     final boolean compressThis = compress && basicFileAttributes.size() > 1024 && isNotNullAndStartsWith(httpHeaders.get(HttpHeaderConstants.CONTENT_TYPE), "text/", "application/");
