91:           return Files.newByteChannel(file);
92:         }
93:       }).then(new Action<ReadableByteChannel>() {
94:         public void execute(ReadableByteChannel fileChannel) {
95:           transmit(basicFileAttributes, new ChunkedInputAdapter(new ChunkedNioStream(fileChannel)));
96:         }
97:       });
98:     }
99:   }
