101:   private void transmit(BasicFileAttributes basicFileAttributes, final Object message) {
102:     HttpResponse response = new CustomHttpResponse(HttpResponseStatus.OK, httpHeaders);
103:     response.headers().set(HttpHeaderConstants.CONTENT_LENGTH, basicFileAttributes.size());
104: 
105:     if (isKeepAlive(request)) {
106:       response.headers().set(HttpHeaderConstants.CONNECTION, HttpHeaderConstants.KEEP_ALIVE);
107:     }
108: 
109:     request.content().release();
110: 
