91:       public void operationComplete(ChannelFuture future) {
92:         closeQuietly(fileChannel);
93:         if (!future.isSuccess()) {
94:           channel.close();
95:         }
96:       }
97:     });
98: 
99:     ChannelFuture lastContentFuture = channel.writeAndFlush(LastHttpContent.EMPTY_LAST_CONTENT);
100:     if (!isKeepAlive(response)) {
101:       lastContentFuture.addListener(ChannelFutureListener.CLOSE);
102:     }
103:   }
104: 
105:   private void closeQuietly(Closeable closeable) {
106:     try {
107:       closeable.close();
108:     } catch (IOException e1) {
