350:       executeEvents(reverseServices, new DefaultEvent(serverRegistry, reloading), Service::onStop, (service, error) ->
351:           LOGGER.warn("Service '" + service.getName() + "' thrown an exception while stopping.", error)
352:       );
353:     }
354:   }
