400:   private <E> void executeEvents(Iterator<? extends Service> services, E event, BiAction<Service, E> action, BiAction<? super Service, ? super Throwable> onError) throws Exception {
401:     if (!services.hasNext()) {
402:       return;
403:     }
404: 
405:     CountDownLatch latch = new CountDownLatch(1);
406:     AtomicReference<Throwable> error = new AtomicReference<>();
407:     executeEvents(services, latch, error, event, action, onError);
408:     latch.await();
409: 
410:     Throwable thrown = error.get();
411:     if (thrown != null) {
412:       throw Exceptions.toException(thrown);
413:     }
414:   }
415: 
416:   private <E> void executeEvents(Iterator<? extends Service> services, CountDownLatch latch, AtomicReference<Throwable> error, E event, BiAction<Service, E> action, BiAction<? super Service, ? super Throwable> onError) throws Exception {
417:     if (services.hasNext()) {
418:       Service service = services.next();
419:       execController.fork()
420:         .onError(t -> {
421:           try {
422:             onError.execute(service, t);
423:           } catch (Throwable e) {
424:             error.set(e);
425:           }
426:         })
427:         .onComplete(e -> {
428:           //noinspection ThrowableResultOfMethodCallIgnored
429:           if (error.get() == null) {
430:             executeEvents(services, latch, error, event, action, onError);
431:           } else {
432:             latch.countDown();
433:           }
434:         })
435:         .start(e -> action.execute(service, event));
436:     } else {
437:       latch.countDown();
438:     }
439:   }
