179:       if (handlerFactoryClass == null) {
180:         throw new LaunchException("No handler factory class specified (config property: " + Property.HANDLER_FACTORY + ")");
181:       }
182: 
183:       int port = getPropertyAsInt(properties, Property.PORT, LaunchConfig.DEFAULT_PORT);
184:       InetAddress address = getPropertyAsInetAddress(properties, Property.ADDRESS);
185:       URI publicAddress = getPropertyAsUri(properties, Property.PUBLIC_ADDRESS);
186:       boolean reloadable = getPropertyAsBoolean(properties, Property.RELOADABLE, false);
187:       int mainThreads = getPropertyAsInt(properties, Property.MAIN_THREADS, 0);
188:       List<String> indexFiles = getPropertyAsList(properties, Property.INDEX_FILES);
189:       InputStream sslKeystore = asStream(properties, Property.SSL_KEYSTORE_FILE, classLoader);
190:       String sslKeystorePassword = properties.getProperty(Property.SSL_KEYSTORE_PASSWORD, "");
