229:   private static InputStream asStream(Properties properties, String key, ClassLoader classLoader) throws IOException {
230:     InputStream stream = null;
231:     String path = properties.getProperty(key);
232:     if (path != null) {
233:       // try to treat it as a File path
234:       File file = new File(path);
235:       if (!file.isFile()) {
236:         // try to treat it as a URL
237:         try {
238:           URL url = new URL(path);
239:           stream = url.openStream();
240:         } catch (MalformedURLException e) {
241:           // try to treat it as a resource path
242:           stream = classLoader.getResourceAsStream(path);
243:         }
244:       } else {
245:         stream = new FileInputStream(file);
246:       }
247:     }
248:     return stream;
249:   }
