251:   private static List<String> getPropertyAsList(Properties properties, String key) {
252:     String delimitedValues = properties.getProperty(key, "");
253:     ImmutableList.Builder<String> trimmed = ImmutableList.builder();
254:     for (String value : delimitedValues.split(",")) {
255:       value = value.trim();
256:       if (!value.isEmpty()) {
257:         trimmed.add(value);
258:       }
259:     }
260:     return trimmed.build();
261:   }
