281:   private static InetAddress getPropertyAsInetAddress(Properties properties, String key) throws UnknownHostException {
282:     String addressString = properties.getProperty(key);
283:     if (addressString == null) {
284:       return null;
285:     } else {
286:       try {
287:         InetAddress address = InetAddress.getByName(addressString);
288:         return address;
289:       } catch (UnknownHostException e) {
290:         throw new IllegalStateException("Failed to resolve requested bind address: " + addressString, e);
291:       }
292:     }
293:   }
