43:     publisher.subscribe(new Subscriber<T>() {
44: 
45:       private Subscription subscription;
46:       private final AtomicBoolean done = new AtomicBoolean();
47: 
48:       @Override
49:       public void onSubscribe(final Subscription subscription) {
50:         this.subscription = subscription;
51:         outSubscriber.onSubscribe(new Subscription() {
52:           @Override
53:           public void request(long n) {
54:             try {
55:               listener.execute(new RequestEvent<>(subscriptionId, n));
56:             } catch (Throwable throwable) {
57:               subscription.cancel();
58:               onError(throwable);
59:               return;
60:             }
61:             subscription.request(n);
62:           }
63: 
64:           @Override
65:           public void cancel() {
66:             try {
67:               listener.execute(new CancelEvent<>(subscriptionId));
68:             } catch (Throwable throwable) {
69:               try {
70:                 subscription.cancel();
71:               } catch (Throwable e) {
72:                 throwable.addSuppressed(e);
73:               }
74:               onError(throwable);
75:               return;
76:             }
77:             subscription.cancel();
78:           }
79:         });
80:       }
