32: /**
33:  * Static methods for the unit testing of handlers.
34:  */
35: public abstract class UnitTest {
36: 
37:   private UnitTest() {
38:   }
39: 
40:   /**
41:    * Unit test a single {@link Handler}.
42:    *
43:    * <pre class="java">
44:    * import ratpack.handling.Handler;
45:    * import ratpack.handling.Context;
46:    * import ratpack.test.handling.HandlingResult;
47:    * import ratpack.test.handling.RequestFixture;
48:    * import ratpack.test.handling.RequestFixtureAction;
49:    * import ratpack.test.UnitTest;
50:    *
51:    * public class Example {
52:    *
53:    *   public static class MyHandler implements Handler {
54:    *     public void handle(Context context) {
55:    *       String outputHeaderValue = context.getRequest().getHeaders().get("input-value") + ":bar";
56:    *       context.getResponse().getHeaders().set("output-value", outputHeaderValue);
57:    *       context.render("received: " + context.getRequest().getPath());
58:    *     }
59:    *   }
60:    *
61:    *   public static void main(String[] args) {
62:    *     HandlingResult result = UnitTest.handle(new MyHandler(), new RequestFixtureAction() {
63:    *       public void execute() {
64:    *         header("input-value", "foo");
65:    *         uri("some/path");
66:    *       }
67:    *     });
68:    *
69:    *     assert result.rendered(String.class).equals("received: some/path");
70:    *     assert result.getHeaders().get("output-value").equals("foo:bar");
71:    *   }
72:    * }
73:    * </pre>
74:    *
75:    * @param handler The handler to invoke
76:    * @param action The configuration of the context for the handler
77:    * @return A result object indicating what happened
78:    * @throws HandlerTimeoutException if the handler takes more than {@link ratpack.test.handling.RequestFixture#timeout(int)} seconds to send a response or call {@code next()} on the context
79:    * @see #handle(Action, Action)
80:    * @see ratpack.test.handling.RequestFixtureAction
81:    */
82:   public static HandlingResult handle(Handler handler, Action<? super RequestFixture> action) throws HandlerTimeoutException {
83:     return buildFixture(action).handle(handler);
84:   }
85: 
86:   /**
87:    * Unit test a {@link Handler} chain.
88:    *
89:    * <pre class="java">
90:    * import ratpack.handling.Context;
91:    * import ratpack.handling.Handler;
92:    * import ratpack.handling.ChainAction;
93:    * import ratpack.test.handling.HandlingResult;
94:    * import ratpack.test.handling.RequestFixtureAction;
95:    * import ratpack.test.UnitTest;
96:    *
97:    * public class Example {
98:    *
99:    *   public static class MyHandlers extends ChainAction {
100:    *     protected void execute() {
101:    *       handler(new Handler() {
102:    *         public void handle(Context context) {
103:    *           String outputHeaderValue = context.getRequest().getHeaders().get("input-value") + ":bar";
104:    *           context.getResponse().getHeaders().set("output-value", outputHeaderValue);
105:    *           context.next();
106:    *         }
107:    *       });
108:    *       handler(new Handler() {
109:    *         public void handle(Context context) {
110:    *           context.render("received: " + context.getRequest().getPath());
111:    *         }
112:    *       });
113:    *     }
114:    *   }
115:    *
116:    *   public static void main(String[] args) {
117:    *     HandlingResult result = UnitTest.handle(new MyHandlers(), new RequestFixtureAction() {
118:    *       public void execute() {
119:    *         header("input-value", "foo");
120:    *         uri("some/path");
121:    *       }
122:    *     });
123:    *
124:    *     assert result.rendered(String.class).equals("received: some/path");
125:    *     assert result.getHeaders().get("output-value").equals("foo:bar");
126:    *   }
127:    * }
128:    * </pre>
129:    *
130:    * @param chainAction the definition of a handler chain to test
131:    * @param requestFixtureAction the configuration of the request fixture
132:    * @return a result object indicating what happened
133:    * @throws HandlerTimeoutException if the handler takes more than {@link ratpack.test.handling.RequestFixture#timeout(int)} seconds to send a response or call {@code next()} on the context
134:    * @see #handle(Handler, Action)
135:    * @see ratpack.test.handling.RequestFixtureAction
136:    */
137:   public static HandlingResult handle(Action<? super Chain> chainAction, Action<? super RequestFixture> requestFixtureAction) throws HandlerTimeoutException {
138:     return buildFixture(requestFixtureAction).handle(chainAction);
139:   }
140: 
141:   /**
142:    * Create a request fixture, for unit testing of {@link Handler handlers}.
143:    *
144:    * @see #handle(Handler, Action)
145:    * @see #handle(Action, Action)
146:    * @return a request fixture
147:    */
148:   public static RequestFixture requestFixture() {
149:     return new DefaultRequestFixture();
150:   }
