152:   /**
153:    * Creates a new execution harness, for unit testing code that produces a promise.
154:    * <pre class="java">
155:    * import ratpack.func.Action;
156:    * import ratpack.func.Function;
157:    * import ratpack.exec.ExecControl;
158:    * import ratpack.exec.Execution;
159:    * import ratpack.exec.Promise;
160:    * import ratpack.exec.Fulfiller;
161:    * import ratpack.test.UnitTest;
162:    * import ratpack.test.exec.ExecHarness;
163:    * import ratpack.test.exec.ExecResult;
164:    * import javax.inject.Inject;
165:    *
166:    * public class Example {
167:    *
168:    *   // An async callback based API
169:    *   static class AsyncApi {
170:    *
171:    *     static interface Callback&lt;T&gt; {
172:    *       void receive(T value);
173:    *     }
174:    *
175:    *     public &lt;T&gt; void returnAsync(final T value, final Callback&lt;? super T&gt; callback) {
176:    *       new Thread() {
177:    *         public void run() {
178:    *           callback.receive(value);
179:    *         }
180:    *       }.run();
181:    *     }
182:    *   }
183:    *
184:    *   // Our service class that wraps the raw async API
185:    *   // In the real app this is created by the DI container (e.g. Guice)
186:    *   static class AsyncService {
187:    *     private final ExecControl execControl;
188:    *     private final AsyncApi asyncApi = new AsyncApi();
189:    *
190:    *     {@literal @}Inject
191:    *     public AsyncService(ExecControl execControl) {
192:    *       this.execControl = execControl;
193:    *     }
194:    *
195:    *     // Our method under test
196:    *     public &lt;T&gt; Promise&lt;T&gt; promise(final T value) {
197:    *       return execControl.promise(new Action&lt;Fulfiller&lt;T&gt;&gt;() {
198:    *         public void execute(final Fulfiller&lt;T&gt; fulfiller) {
199:    *           asyncApi.returnAsync(value, new AsyncApi.Callback&lt;T&gt;() {
200:    *             public void receive(T returnedValue) {
201:    *               fulfiller.success(returnedValue);
202:    *             }
203:    *           });
204:    *         }
205:    *       });
206:    *     }
207:    *   }
208:    *
209:    *
210:    *   // Our test
211:    *   public static void main(String[] args) throws Throwable {
212:    *
213:    *     // the harness must be close()'d when finished with to free resources
214:    *     try(ExecHarness harness = UnitTest.execHarness()) {
215:    *
216:    *       // set up the code under test using the exec control from the harness
217:    *       final AsyncService service = new AsyncService(harness.getControl());
218:    *
219:    *       // exercise the async code using the harness, blocking until the promised value is available
220:    *       ExecResult<String> result = harness.execute(new Function&lt;Execution, Promise&lt;String&gt;&gt;() {
221:    *         public Promise&lt;String&gt; apply(Execution execution) {
222:    *           // execute the code under test
223:    *           return service.promise("foo");
224:    *         }
225:    *       });
226:    *
227:    *       assert result.getValue() == "foo";
228:    *     }
229:    *   }
230:    * }
231:    * </pre>
232:    *
233:    * @return An exec harness
234:    */
235:   public static ExecHarness execHarness() {
236:     return new DefaultExecHarness(LaunchConfigBuilder.noBaseDir().build().getExecController());
237:   }
238: 
239:   private static RequestFixture buildFixture(Action<? super RequestFixture> action) {
240:     RequestFixture fixture = requestFixture();
241:     try {
242:       action.execute(fixture);
243:     } catch (Exception e) {
244:       throw uncheck(e);
245:     }
246:     return fixture;
247:   }
248: 
249: }
