259:           response.headers().set(HttpHeaders.Names.CONNECTION, HttpHeaders.Values.KEEP_ALIVE);
260:         }
261:         shouldClose = false;
262:       }
263:       ChannelFuture future = channel.writeAndFlush(response);
264:       if (shouldClose) {
265:         future.addListener(ChannelFutureListener.CLOSE);
